/** Turns labels like "Iro & Buba" or "Two Piece Suit" into registry ids ("iro-and-buba", "two-piece-suit"). */
export function toGarmentId(label: string): string {
  return label.trim().toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

/** Look up an icon by id, alias or display label. Unknown values fall back to the T-shirt icon. */
export function getGarmentIcon(idOrLabel: string | null | undefined): GarmentIconMeta {
  if (!idOrLabel) return GARMENT_ICONS[FALLBACK_GARMENT_ICON];
  const key = toGarmentId(idOrLabel);
  const id = (key in GARMENT_ICONS ? key : ALIASES[key]) as GarmentIconId | undefined;
  return GARMENT_ICONS[id ?? FALLBACK_GARMENT_ICON];
}

/** Returns true when an id or label resolves to a dedicated icon (not the fallback). */
export function hasGarmentIcon(idOrLabel: string): boolean {
  const key = toGarmentId(idOrLabel);
  return key in GARMENT_ICONS || key in ALIASES;
}

export function getGarmentIconsByCategory(category: GarmentCategory): GarmentIconMeta[] {
  return Object.values(GARMENT_ICONS).filter((icon) => icon.category === category);
}
